18|export const DEFAULT_CITY = {
19|  seed: 1989,
20|  blocksX: 8, // block columns (west -> east)
21|  blocksZ: 7, // block rows (north -> south), one of them becomes the river
22|  blockMin: 70, // block edge length range in metres
23|  blockMax: 105,
24|  streetWidth: 14,
25|  boulevardWidth: 36,
26|  medianWidth: 8,
27|  riverWidth: 46,
28|  sidewalk: 4,
29|  curbHeight: 0.15,
30|};
31|
32|const NAMES_NS = ['Friedrichstraße', 'Schönhauser Allee', 'Kastanienallee', 'Rosenthaler Straße', 'Chausseestraße', 'Brunnenstraße', 'Wilhelmstraße', 'Mehringdamm', 'Kottbusser Damm', 'Prenzlauer Allee', 'Greifswalder Straße', 'Warschauer Straße'];
