34|const NAMES_UFER = ['Reichpietschufer', 'Schiffbauerdamm', 'Märkisches Ufer', 'Fraenkelufer', 'Paul-Lincke-Ufer', 'Maybachufer'];
35|
36|/** Colors are stored as 0xRRGGBB so the data stays renderer-agnostic. */
37|const PALETTE = {
38|  altbau: [0xe8dcc0, 0xd9b77e, 0xd99a82, 0xc9b79c, 0xbdbdb5, 0xe5d38f, 0xa9b8a6, 0x9fb0bf, 0xedebe4, 0xa65e46],
