43|export function generateCity(options = {}) {
44|  const cfg = { ...DEFAULT_CITY, ...options };
45|  if (cfg.blocksX < 4 || cfg.blocksZ < 5) throw new RangeError('City needs at least 4x5 blocks.');
46|  const root = new Rng(cfg.seed);
47|  const layoutRng = root.fork('layout');
48|  const nameRng = root.fork('names');
49|  const treeRng = root.fork('trees');
50|
51|  // 1. Pick the special rows: the river replaces one block row, the boulevard is one E-W street.
52|  const riverRow = layoutRng.int(Math.ceil(cfg.blocksZ / 2), cfg.blocksZ - 2);
53|  const boulevard = layoutRng.int(2, riverRow - 1);
54|
55|  // 2. Lay out streets and blocks along both axes.
56|  const blockSize = () => layoutRng.range(cfg.blockMin, cfg.blockMax);
57|  const xs = layoutAxis(cfg.blocksX, blockSize, () => cfg.streetWidth);
58|  const zs = layoutAxis(
59|    cfg.blocksZ,
60|    (r) => (r === riverRow ? cfg.riverWidth : blockSize()),
61|    (k) => (k === boulevard ? cfg.boulevardWidth : cfg.streetWidth),
62|  );
63|  const bounds = { x0: -xs.extent / 2, z0: -zs.extent / 2, x1: xs.extent / 2, z1: zs.extent / 2 };
