76|  const bridges = [];
77|  streetsNS.forEach((s, i) => {
78|    const forced = i === 2 || i === Math.floor(cfg.blocksX / 2) + 1;
79|    if (forced || layoutRng.chance(0.6)) bridges.push({ street: i, x0: s.center - s.width / 2, x1: s.center + s.width / 2 });
80|  });
