82|
83|  // 5. Landmarks: a city gate on the boulevard, a TV tower on a plaza.
84|  const bz = streetsEW[boulevard].center;
85|  const gateCol = xs.blocks[1];
86|  const gateWidth = cfg.boulevardWidth - 2;
87|  const gate = {
88|    kind: 'gate',
89|    x: (gateCol.start + gateCol.end) / 2,
90|    z: bz,
91|    width: gateWidth,
92|    pillars: Array.from({ length: 6 }, (_, i) => bz - gateWidth / 2 + 0.9 + (i * (gateWidth - 1.8)) / 5),
