167|    box(bounds.x0 - t, bounds.z1, bounds.x1 + t, bounds.z1 + t, 'border'),
168|    box(bounds.x0 - t, bounds.z0, bounds.x0, bounds.z1, 'border'),
169|    box(bounds.x1, bounds.z0, bounds.x1 + t, bounds.z1, 'border'),
170|  );
171|
172|  // 11. Spawn: right-hand lane of the boulevard, just east of the gate, heading east.
173|  const spawn = { x: gate.x + 30, z: bz + cfg.medianWidth / 2 + 3.5, heading: Math.PI / 2 };
174|
175|  return { seed: cfg.seed, config: cfg, bounds, streetsNS, streetsEW, river, blocks, medians, markings, trees, landmarks, colliders, spawn };
