178|/** Returns a human-readable location like "Torstraße / Friedrichstraße". */
179|export function streetAt(city, x, z) {
180|  const on = (s, v) => Math.abs(v - s.center) <= s.width / 2;
181|  const ns = city.streetsNS.find((s) => on(s, x));
