8|
9|// A wired-up server + client handles on the virtual network. Each client
10|// records every message it is sent as {type, data}; `client.send(type, data)`
11|// encodes + delivers with the client's injected latency.
12|function world({ latency = 0 } = {}) {
13|  const net = new FakeNet();
14|  const server = new FakeServer(net);
15|  const race = createRaceState({
16|    seed: 42,
17|    now: () => net.now,
18|    send: (conn, type, data) => conn.send(encode(type, data)),
19|    close: (conn, code, reason) => conn.close(code, reason),
20|    schedule: (delayMs, fn) => net.schedule(delayMs, fn),
21|  });
22|  server.onConnect = (conn) => {
23|    race.connect(conn);
24|    conn.onMessage = (text) => race.onMessage(conn, text);
25|    conn.onClose = () => race.disconnect(conn);
26|  };
27|  const client = (opts) => {
28|    const conn = server.connect({ latency });
29|    const me = { conn, messages: [], id: null, closedWith: null };
30|    conn.onMessage = (text) => {
31|      const m = decode(text);
32|      me.messages.push(m);
33|      if (m.type === 'roster') me.id = m.data.players.find((p) => p.name === me.name)?.id ?? me.id;
34|    };
35|    conn.onClose = () => { me.closedWith = conn.closedWith; };
36|    me.name = null;
37|    me.join = (name) => {
38|      me.name = name;
39|      conn.send(encode('join', { name }));
40|      return me;
41|    };
42|    me.send = (type, data) => conn.send(encode(type, data));
43|    me.saw = (type) => me.messages.filter((m) => m.type === type);
44|    return me;
45|  };
46|  return { net, race, client };
47|}
